def __init__(self, store: AipActionStore, adapters: ActionAdapterRegistry) -> None:
        self._store = store
        self._adapters = adapters

def get_execution_view_for_scope(
        self, scope: TenantScope, proposal_id: str
    ) -> ActionExecutionView:
        """Read the same projection for an already authenticated tenant-bound caller."""
        with connect(scope) as conn:
            lease = conn.execute(
                """SELECT * FROM aip_action_execution_lease
                   WHERE org_id=%s AND project_id=%s AND proposal_id=%s
                   ORDER BY attempt DESC, created_at DESC LIMIT 1""",
                (*scope.key, proposal_id),
            ).fetchone()
        return self._view(scope, proposal_id, lease)

def __init__(self, connect_factory: ConnectFactory | None = None, *, bootstrap_guard=None,
                 network_activation_guard=None, network_approval_guard=None,
                 first_content_guard=None, guard_activation_guard=None, guard_approval_guard=None,
                 model_eval_guard=None, source_license_guard=None, source_license_approval_guard=None,
                 provider_capacity_guard=None, provider_capacity_source_guard=None) -> None:
        if source_license_approval_guard is not None:
            from aos_api.aip_license_source_approval import SourceLicenseApprovalGuard
            if type(source_license_approval_guard) is not SourceLicenseApprovalGuard:
                raise TypeError('exact source license approval guard required')
        self._source_license_approval_guard = source_license_approval_guard
        if source_license_guard is not None:
            from aos_api.aip_license_source_proposal import SourceLicenseProposalGuard
            if type(source_license_guard) is not SourceLicenseProposalGuard:
                raise TypeError('exact source license proposal guard required')
        self._source_license_guard = source_license_guard
        if model_eval_guard is not None:
            from aos_api.aip_model_eval_action import ModelEvalActionGuard
            if type(model_eval_guard) is not ModelEvalActionGuard:
                raise TypeError('exact Model Eval Action guard required')
        self._model_eval_guard = model_eval_guard
        if provider_capacity_guard is not None:
            from aos_api.aip_provider_capacity_action import ProviderCapacityActionGuard
            if type(provider_capacity_guard) is not ProviderCapacityActionGuard:
                raise TypeError('exact Provider capacity Action guard required')
        self._provider_capacity_guard = provider_capacity_guard
        if provider_capacity_source_guard is not None:
            from aos_api.aip_provider_capacity_source_action import ProviderCapacitySourceActionGuard
            if type(provider_capacity_source_guard) is not ProviderCapacitySourceActionGuard:
                raise TypeError('exact Provider capacity Source Action guard required')
        self._provider_capacity_source_guard = provider_capacity_source_guard
        if guard_approval_guard is not None:
            from aos_api.aip_guard_policy_activation import GuardPolicyApprovalGuard
            if type(guard_approval_guard) is not GuardPolicyApprovalGuard:
                raise TypeError('exact guard policy approval guard required')
        self._guard_approval_guard = guard_approval_guard
        if guard_activation_guard is not None:
            from aos_api.aip_guard_policy_activation import GuardPolicyActivationGuard
            if type(guard_activation_guard) is not GuardPolicyActivationGuard:
                raise TypeError('exact guard policy activation guard required')
        self._guard_activation_guard = guard_activation_guard
        if first_content_guard is not None:
            from aos_api.ecommerce_content_first_action_binding import FirstContentActionGuard
            if type(first_content_guard) is not FirstContentActionGuard:
                raise TypeError('exact first content guard required')
        self._first_content_guard = first_content_guard
        if bootstrap_guard is not None:
            from aos_api.ecommerce_analysis_bootstrap_action import _BootstrapActionGuard
            if type(bootstrap_guard) is not _BootstrapActionGuard:
                raise TypeError('exact bootstrap action guard required')
        self._bootstrap_guard = bootstrap_guard
        if network_activation_guard is not None:
            from aos_api.aip_network_policy_action_producer import NetworkPolicyActivationGuard
            if type(network_activation_guard) is not NetworkPolicyActivationGuard:
                raise TypeError('exact network activation guard required')
        self._network_activation_guard = network_activation_guard
        if network_approval_guard is not None:
            from aos_api.aip_network_policy_action_producer import NetworkPolicyApprovalGuard
            if type(network_approval_guard) is not NetworkPolicyApprovalGuard:
                raise TypeError('exact network approval guard required')
        self._network_approval_guard = network_approval_guard
        self._connect_factory = connect_factory or db_connect

def get_proposal(self, scope: TenantScope, proposal_id: str) -> ActionDraftBundle:
        with self._connect(scope) as conn:
            return self._bundle(conn, scope, proposal_id)

def _connect(self, scope: TenantScope):
        try:
            return self._connect_factory(scope)
        except TypeError:
            return self._connect_factory()

def list(self, scope: TenantScope, *, limit: int = 100) -> MediaFinanceListResponse:
        if not 1 <= limit <= 100:
            raise MediaFinanceConflict("MEDIA_FINANCE_LIMIT_INVALID")
        with self._connect(scope) as conn:
            rows = conn.execute(
                """SELECT finance_id FROM aip_media_attempt_finance
                   WHERE org_id=%s AND project_id=%s ORDER BY created_at DESC,finance_id LIMIT %s""",
                (*scope.key, limit),
            ).fetchall()
            items = [self.get(scope, row["finance_id"], conn=conn) for row in rows]
            return MediaFinanceListResponse(tenant=self._tenant(scope), items=items, count=len(items))

def get(self, scope: TenantScope, finance_id: str, *, conn: Any | None = None) -> MediaFinanceSnapshot:
        def read(connection: Any) -> MediaFinanceSnapshot:
            row = connection.execute(
                "SELECT base_payload FROM aip_media_attempt_finance WHERE org_id=%s AND project_id=%s AND finance_id=%s",
                (*scope.key, finance_id),
            ).fetchone()
            if row is None:
                raise MediaFinanceNotFound(finance_id)
            events = connection.execute(
                """SELECT version,event_kind,payload,content_hash,actor,created_at
                   FROM aip_media_attempt_finance_event
                   WHERE org_id=%s AND project_id=%s AND finance_id=%s ORDER BY version""",
                (*scope.key, finance_id),
            ).fetchall()
            return self._reduce(scope, self._load(row["base_payload"]), events)

        if conn is not None:
            return read(conn)
        with self._connect(scope) as connection:
            return read(connection)

def list_production_contexts(
        self, scope: TenantScope
    ) -> ProductionContextListResponse:
        with self._connect_factory(scope) as conn:
            rows = conn.execute(
                """SELECT * FROM aip_production_context_revision
                   WHERE org_id=%s AND project_id=%s
                   ORDER BY created_at DESC, context_id, revision DESC""",
                scope.key,
            ).fetchall()
            items = [self._production_context(scope, row) for row in rows]
            return ProductionContextListResponse(
                tenant=self._tenant(scope), items=items, count=len(items)
            )

def _production_context(
        self, scope: TenantScope, row: Any
    ) -> ProductionContextRevision:
        preparation = self._load(row["preparation_ref"])
        return ProductionContextRevision(
            tenant=self._tenant(scope),
            context_id=row["context_id"],
            revision=int(row["revision"]),
            task_id=row["task_id"],
            brief_ref=ExactRevisionRef.model_validate(self._load(row["brief_ref"])),
            evidence_bundle_ref=ExactRevisionRef.model_validate(
                self._load(row["evidence_bundle_ref"])
            ),
            eval_contract_ref=ExactRevisionRef.model_validate(
                self._load(row["eval_contract_ref"])
            ),
            responsibility_plan_ref=ExactRevisionRef.model_validate(
                self._load(row["responsibility_plan_ref"])
            ),
            production_profile_ref=None
            if self._load(row["production_profile_ref"]) is None
            else ExactRevisionRef.model_validate(
                self._load(row["production_profile_ref"])
            ),
            preparation_ref=None
            if preparation is None
            else ExactRevisionRef.model_validate(preparation),
            profile=row["profile"],
            dependency_snapshot=self._load(row["dependency_snapshot"]),
            dependency_snapshot_hash=row["dependency_snapshot_hash"],
            content_hash=row["content_hash"],
            lifecycle=row["lifecycle"],
            readiness=row["readiness"],
            blockers=[
                ContractBlocker.model_validate(item)
                for item in (self._load(row["blockers"]) or [])
            ],
            created_by=row["created_by"],
            created_at=row["created_at"],
        )

def list_return_decisions(
        self, scope: TenantScope, *, issue_id: str | None = None
    ) -> ReturnDecisionListResponse:
        with self._connect_factory(scope) as conn:
            if issue_id:
                rows = conn.execute(
                    """SELECT * FROM aip_return_decision
                       WHERE org_id=%s AND project_id=%s AND issue_id=%s
                       ORDER BY created_at DESC, decision_id DESC""",
                    (*scope.key, issue_id),
                ).fetchall()
            else:
                rows = conn.execute(
                    """SELECT * FROM aip_return_decision
                       WHERE org_id=%s AND project_id=%s
                       ORDER BY created_at DESC, decision_id DESC""",
                    scope.key,
                ).fetchall()
            items = [self._return_decision(scope, row) for row in rows]
            return ReturnDecisionListResponse(
                tenant=self._tenant(scope), items=items, count=len(items)
            )

def list_review_issues(self, scope: TenantScope) -> ReviewIssueListResponse:
        with self._connect_factory(scope) as conn:
            rows = conn.execute(
                """SELECT * FROM aip_review_issue
                WHERE org_id=%s AND project_id=%s
                ORDER BY updated_at DESC,issue_id""",
                scope.key,
            ).fetchall()
            items = [self._review_issue(scope, row) for row in rows]
            return ReviewIssueListResponse(
                tenant=self._tenant(scope), items=items, count=len(items)
            )

def list_media_gate_sets(self, scope: TenantScope) -> MediaGateSetListResponse:
        with self._connect_factory(scope) as conn:
            rows = conn.execute(
                """SELECT * FROM aip_media_gate_set_decision
                WHERE org_id=%s AND project_id=%s ORDER BY created_at DESC,gate_set_id""",
                scope.key,
            ).fetchall()
            items = [self._media_gate_set(scope, row) for row in rows]
            return MediaGateSetListResponse(
                tenant=self._tenant(scope), items=items, count=len(items)
            )

def list_artifact_families(self, scope: TenantScope) -> ArtifactFamilyListResponse:
        with self._connect_factory(scope) as conn:
            rows = conn.execute(
                """SELECT * FROM aip_artifact_family_head
                WHERE org_id=%s AND project_id=%s
                ORDER BY updated_at DESC,family_id""",
                scope.key,
            ).fetchall()
            items = [self._artifact_family_view(conn, scope, row) for row in rows]
            return ArtifactFamilyListResponse(
                tenant=self._tenant(scope), items=items, count=len(items)
            )

def _sorted_artifact_refs(refs: list[ExactArtifactRef]) -> list[dict[str, str]]:
        return sorted(
            (item.model_dump(mode="json", by_alias=True) for item in refs),
            key=lambda item: (item["artifactId"], item["contentHash"]),
        )

def get_responsibility_plan(self, scope: TenantScope, plan_id: str, revision: int | None = None,
                                *, conn: Any | None = None) -> ResponsibilityPlanRevision:
        def read(c: Any) -> ResponsibilityPlanRevision:
            head = c.execute("SELECT * FROM public.aip_responsibility_plan_head WHERE org_id=%s AND project_id=%s AND plan_id=%s", (*scope.key, plan_id)).fetchone()
            if not head:
                raise ProductionContractNotFound("responsibility plan not found")
            selected = revision or int(head["current_revision"])
            row = c.execute("SELECT * FROM public.aip_responsibility_plan_revision WHERE org_id=%s AND project_id=%s AND plan_id=%s AND revision=%s", (*scope.key, plan_id, selected)).fetchone()
            if not row:
                raise ProductionContractNotFound("responsibility plan revision not found")
            return self._responsibility_plan(scope, row, int(head["version"]), c)
        if conn is not None:
            return read(conn)
        with self._connect_factory(scope) as c:
            return read(c)

def _require_exact_assignee_resolution(
        self,
        conn: Any,
        scope: TenantScope,
        receipt_id: str,
        assignee: AssigneeRef,
        required_capability_ids: set[str],
        slot_id: str,
        *,
        lock_human_membership: bool = False,
        lock_provider_binding: bool = False,
        lock_tool_binding: bool = False,
        lock_agent_binding: bool = False,
    ) -> None:
        row = conn.execute(
            """SELECT subject_id,kind,resource_id,version,status,selected_assignee,
                      required_capability_refs,binding_refs,snapshot_hash,expires_at
                 FROM public.aip_assignee_resolution_receipt
                WHERE org_id=%s AND project_id=%s AND receipt_id=%s""",
            (*scope.key, receipt_id),
        ).fetchone()
        if row is None:
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_MISSING:{slot_id}"
            )
        if row["subject_id"] != slot_id:
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_SUBJECT_DRIFTED:{slot_id}"
            )
        if row["status"] != "resolved" or not row["snapshot_hash"]:
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_NOT_EXACT:{slot_id}"
            )
        if row["expires_at"] is None or row["expires_at"] <= datetime.now(timezone.utc):
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_STALE:{slot_id}"
            )
        if (
            row["kind"] != assignee.kind.value
            or row["resource_id"] != assignee.resource_id
            or int(row["version"]) != assignee.version
        ):
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_DRIFTED:{slot_id}"
            )
        selected = self._load(row["selected_assignee"])
        if selected != assignee.model_dump(mode="json", by_alias=True):
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_SELECTION_DRIFTED:{slot_id}"
            )
        if assignee.kind.value == "human_principal" and conn.execute(
            """SELECT 1 FROM meta_membership
                WHERE org_id=%s AND project_id=%s AND subject=%s"""
            + (" FOR SHARE" if lock_human_membership else ""),
            (*scope.key, assignee.resource_id),
        ).fetchone() is None:
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_MEMBERSHIP_REVOKED:{slot_id}"
            )
        capabilities = self._load(row["required_capability_refs"]) or []
        resolved_ids = {
            item.get("assetId")
            for item in capabilities
            if isinstance(item, dict) and item.get("assetType") == "CapabilityRevision"
        }
        if not required_capability_ids <= resolved_ids:
            raise ProductionContractDependencyBlocked(
                f"ASSIGNEE_RESOLUTION_CAPABILITY_DRIFTED:{slot_id}"
            )
        if assignee.kind.value in {
            "provider_capability_binding", "tool_binding", "agent_instance"
        }:
            if lock_provider_binding and assignee.kind.value == "provider_capability_binding":
                conn.execute(
                    """SELECT 1 FROM aip_capability_binding
                        WHERE org_id=%s AND project_id=%s AND binding_id=%s
                        FOR SHARE""",
                    (*scope.key, assignee.resource_id),
                ).fetchone()
            if lock_tool_binding and assignee.kind.value == "tool_binding":
                tool_row = conn.execute(
                    """SELECT agent_instance_id,capability_binding_ids
                        FROM aip_tool_binding
                        WHERE org_id=%s AND project_id=%s AND binding_id=%s
                        FOR SHARE""",
                    (*scope.key, assignee.resource_id),
                ).fetchone()
                if tool_row is not None:
                    conn.execute(
                        """SELECT 1 FROM aip_agent_instance
                            WHERE org_id=%s AND project_id=%s AND instance_id=%s
                            FOR SHARE""",
                        (*scope.key, tool_row["agent_instance_id"]),
                    ).fetchone()
                    binding_ids = AipAssigneeResolutionStore._binding_ids(
                        tool_row["capability_binding_ids"]
                    )
                    if binding_ids:
                        conn.execute(
                            """SELECT 1 FROM aip_capability_binding
                                WHERE org_id=%s AND project_id=%s
                                  AND binding_id=ANY(%s)
                                ORDER BY binding_id FOR SHARE""",
                            (*scope.key, sorted(set(binding_ids))),
                        ).fetchall()
            if lock_agent_binding and assignee.kind.value == "agent_instance":
                conn.execute(
                    """SELECT 1 FROM aip_agent_instance
                        WHERE org_id=%s AND project_id=%s AND instance_id=%s
                        FOR SHARE""",
                    (*scope.key, assignee.resource_id),
                ).fetchone()
                refs = self._load(row["binding_refs"]) or []
                for asset_type, table in (
                    ("SkillBinding", "aip_skill_binding"),
                    ("CapabilityBinding", "aip_capability_binding"),
                ):
                    ids = sorted({
                        ref.get("assetId") for ref in refs
                        if isinstance(ref, dict) and ref.get("assetType") == asset_type
                        and isinstance(ref.get("assetId"), str)
                    })
                    if ids:
                        conn.execute(
                            f"""SELECT 1 FROM {table}
                                WHERE org_id=%s AND project_id=%s AND binding_id=ANY(%s)
                                ORDER BY binding_id FOR SHARE""",
                            (*scope.key, ids),
                        ).fetchall()
            kind = (
                "PROVIDER_BINDING"
                if assignee.kind.value == "provider_capability_binding"
                else "TOOL_BINDING" if assignee.kind.value == "tool_binding"
                else "AGENT_BINDING"
            )
            try:
                required = [VersionedAssetRef.model_validate(item) for item in capabilities]
                frozen_refs = [
                    VersionedAssetRef.model_validate(item)
                    for item in (self._load(row["binding_refs"]) or [])
                ]
                decision = AipAssigneeResolutionStore()._evaluate_candidate(
                    conn, scope,
                    ResolveAssigneeRequest(
                        subject_id=slot_id, candidates=[assignee],
                        required_capabilities=required,
                    ),
                    assignee, datetime.now(timezone.utc),
                )
            except (TypeError, ValueError) as exc:
                raise ProductionContractDependencyBlocked(
                    f"ASSIGNEE_RESOLUTION_{kind}_DRIFTED:{slot_id}"
                ) from exc
            if assignee.kind.value == "agent_instance":
                skill_refs = [
                    ref for ref in frozen_refs if ref.asset_type == "SkillBinding"
                ]
                if not skill_refs or any(
                    conn.execute(
                        """SELECT 1 FROM aip_skill_binding b
                            JOIN aip_skill_template_revision s
                              ON s.skill_id=b.skill_id AND s.revision=b.skill_revision
                            WHERE b.org_id=%s AND b.project_id=%s
                              AND b.binding_id=%s AND b.instance_id=%s
                              AND b.version=%s AND b.status='active'
                              AND s.lifecycle='published'
                              AND s.publication_tenant->>'orgId'=%s
                              AND s.publication_tenant->>'projectId'=%s
                              AND (SELECT latest.lifecycle
                                   FROM aip_skill_template_revision latest
                                   WHERE latest.skill_id=b.skill_id
                                   ORDER BY latest.revision DESC LIMIT 1)='published'
                              AND EXISTS (SELECT 1 FROM aip_agent_registry_receipt r
                                  WHERE r.org_id=b.org_id AND r.project_id=b.project_id
                                    AND r.operation='skill_binding.create'
                                    AND r.status='applied'
                                    AND r.result_ref->>'resourceId'=b.binding_id)
                              AND EXISTS (SELECT 1 FROM aip_agent_registry_receipt r
                                  WHERE r.org_id=b.org_id AND r.project_id=b.project_id
                                    AND r.operation='skill_binding.evaluate'
                                    AND r.status='applied'
                                    AND r.result_ref->>'resourceId'=b.binding_id)
                              AND EXISTS (SELECT 1 FROM aip_agent_registry_receipt r
                                  WHERE r.org_id=b.org_id AND r.project_id=b.project_id
                                    AND r.operation='skill_binding.update'
                                    AND r.status='applied'
                                    AND r.result_ref->>'resourceId'=b.binding_id)""",
                        (*scope.key, ref.asset_id, assignee.resource_id,
                         ref.revision, *scope.key),
                    ).fetchone() is None
                    for ref in skill_refs
                ):
                    raise ProductionContractDependencyBlocked(
                        f"ASSIGNEE_RESOLUTION_AGENT_SOURCE_INVALID:{slot_id}"
                    )
            if decision.status is not AssigneeResolutionStatus.RESOLVED:
                raise ProductionContractDependencyBlocked(
                    f"ASSIGNEE_RESOLUTION_{kind}_REVOKED:{slot_id}"
                )
            if not frozen_refs or frozen_refs != decision.binding_refs:
                raise ProductionContractDependencyBlocked(
                    f"ASSIGNEE_RESOLUTION_{kind}_DRIFTED:{slot_id}"
                )

def _capability_identifier(ref: Any) -> str | None:
        """Skill/capability bindings may store plain ids or ResourceRef-shaped objects."""
        if isinstance(ref, str):
            value = ref.strip()
            return value or None
        if isinstance(ref, dict):
            value = ref.get("assetId") or ref.get("resourceId") or ref.get("capabilityId")
            if isinstance(value, str):
                value = value.strip()
                return value or None
        return None

def __init__(self, *, connect_factory: ConnectFactory | None = None) -> None:
        self._connect_factory = connect_factory or partial(
            connect_read_only, inherit_scope=False
        )

def read(
        self,
        *,
        org_id: str,
        project_id: str,
        object_type: ObjectType,
        cutoff: datetime,
        limit: int = 50,
    ) -> list[OperationsObjectRef]:
        if cutoff.utcoffset() is None:
            raise ValueError("operations object cutoff requires a timezone")
        if object_type not in _OBJECT_TYPES:
            raise ValueError("unsupported operations object type")
        if not 1 <= limit <= 50:
            raise ValueError("operations object limit must be between 1 and 50")
        scope = TenantScope(org_id=org_id, project_id=project_id)
        try:
            with self._connect_factory() as conn:
                apply_transaction_scope(conn, scope)
                rows = conn.execute(
                    "SELECT object_type,external_id,source_updated_at,payload_hash "
                    "FROM ecom_object WHERE org_id=%s AND workspace_id=%s "
                    "AND object_type=%s AND deleted_at IS NULL AND source_updated_at<=%s "
                    "ORDER BY source_updated_at DESC,external_id DESC LIMIT %s",
                    (*scope.key, object_type, cutoff, limit),
                ).fetchall()
            items = []
            for row in rows:
                if row["object_type"] != object_type:
                    raise ValueError("operations object type drift")
                items.append(
                    OperationsObjectRef(
                        object_type=row["object_type"],
                        object_id=row["external_id"],
                        content_hash="sha256:" + row["payload_hash"],
                        source_updated_at=row["source_updated_at"],
                    )
                )
            return items
        except (psycopg.Error, KeyError, TypeError, ValueError) as exc:
            raise OperationsObjectReadError(
                "canonical Operations object read failed closed"
            ) from exc

